#define _DEFAULT_SOURCE
#define _XOPEN_SOURCE 600

#include <errno.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "../../../indigo_test/simulator_common/serial_simulator_common.h"

typedef struct {
	bool headless;
	bool trace;
	const char *ready_file;
} simulator_options;

static simulator_options options = {
	.headless = false,
	.trace = true,
	.ready_file = NULL
};

static const char *simulator_name = "gps_nmea";
static volatile sig_atomic_t running = 1;
static int serial_fd = -1;

static void usage(const char *name) {
	printf("Generic NMEA 0183 GPS serial simulator\n");
	printf("Usage: %s [OPTIONS]\n", name);
	printf("  --headless              Disable terminal-oriented output\n");
	printf("  --ready-file <path>     Write INDIGO_SIMULATOR_PORT after PTY setup\n");
	printf("  --trace                 Log protocol requests and replies\n");
	printf("  -h, --help              Show this help and exit\n");
}

static void signal_handler(int sig) {
	(void)sig;
	running = 0;
	if (serial_fd >= 0) {
		close(serial_fd);
		serial_fd = -1;
	}
}

static bool parse_args(int argc, char *argv[]) {
	for (int i = 1; i < argc; i++) {
		if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
			usage(argv[0]);
			exit(0);
		} else if (!strcmp(argv[i], "--headless")) {
			options.headless = true;
			options.trace = false;
		} else if (!strcmp(argv[i], "--trace")) {
			options.trace = true;
		} else if (!strcmp(argv[i], "--ready-file")) {
			if (++i == argc) {
				fprintf(stderr, "--ready-file requires a path\n");
				return false;
			}
			options.ready_file = argv[i];
		} else {
			fprintf(stderr, "Unknown option '%s'\n", argv[i]);
			return false;
		}
	}
	return true;
}

static void send_sentence(const char *payload) {
	unsigned char checksum = 0;
	for (const char *p = payload; *p; p++) {
		checksum ^= (unsigned char)*p;
	}

	char line[160];
	snprintf(line, sizeof(line), "$%s*%02X\r\n", payload, checksum);
	if (options.trace) {
		fprintf(stderr, "-> %s", line);
	}
	serial_simulator_write_all(serial_fd, line, strlen(line));
}

static void send_cycle(void) {
	send_sentence("GPRMC,123519,A,4807.038,N,01131.000,E,000.0,000.0,230394,,,A");
	send_sentence("GPGGA,123520,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,");
	send_sentence("GPGSA,A,3,04,05,09,12,24,25,29,31,,,,,1.8,1.0,1.5");
	send_sentence("GPGSV,2,1,08,04,77,045,42,05,65,120,43,09,45,210,41,12,32,300,40");
	send_sentence("GPGSV,2,2,08,24,22,180,39,25,18,250,38,29,10,090,37,31,06,330,36");
}

static void run_protocol_loop(void) {
	while (running) {
		send_cycle();
		for (int i = 0; running && i < 10; i++) {
			usleep(100000);
		}
	}
}

int main(int argc, char *argv[]) {
	char port[256] = { 0 };

	if (!parse_args(argc, argv)) {
		return 1;
	}
	signal(SIGTERM, signal_handler);
	signal(SIGINT, signal_handler);

	serial_fd = serial_simulator_open_pty(port, sizeof(port));
	if (serial_fd < 0) {
		return 1;
	}
	if (options.ready_file != NULL && !serial_simulator_write_ready_file(options.ready_file, simulator_name, port)) {
		close(serial_fd);
		return 1;
	}
	if (!options.headless) {
		printf("Generic NMEA 0183 GPS simulator ready on %s\n", port);
	}

	run_protocol_loop();
	if (serial_fd >= 0) {
		close(serial_fd);
	}
	return 0;
}
